function initFlowAnimation(){
 const root=document.querySelector('[data-flow-animation]'); if(!root)return;
 const stages=[...root.querySelectorAll('[data-flow-stage]')], links=[...root.querySelectorAll('[data-flow-connector]')];
 const reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const replay=()=>{root.classList.remove('flow-play');stages.forEach(x=>x.classList.remove('flow-in'));links.forEach(x=>x.classList.remove('flow-link-in'));if(reduced){root.classList.add('flow-static');return}requestAnimationFrame(()=>{root.classList.add('flow-play');stages.forEach((x,i)=>setTimeout(()=>x.classList.add('flow-in'),i*480));links.forEach((x,i)=>setTimeout(()=>x.classList.add('flow-link-in'),i*480+300))})};
 root._replayFlow=replay;
 if(reduced){root.classList.add('flow-static');stages.forEach(x=>x.classList.add('flow-in'));links.forEach(x=>x.classList.add('flow-link-in'));return}
 if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){replay();io.disconnect()}},{threshold:.18});io.observe(root)}else replay();
}

