function maChart(values, cls='ma-chart', color='#18c8f5'){
 const w=900,h=270,px=42,py=18,min=Math.min(...values),max=Math.max(...values),span=max-min||1;
 const pts=values.map((v,i)=>[px+i*(w-px*2)/(values.length-1),h-py-(v-min)/span*(h-py*2)]);
 const poly=pts.map(p=>p.join(',')).join(' ');
 const line=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');
 const area=line+` L ${pts.at(-1)[0]} ${h-py} L ${pts[0][0]} ${h-py} Z`;
 const gid='g'+Math.random().toString(36).slice(2,8);
 return `<svg class="${cls}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Illustrative historical performance chart"><defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".34"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${[.18,.38,.58,.78,.98].map(y=>`<line x1="${px}" y1="${h*y}" x2="${w-px}" y2="${h*y}" class="ma-gridline"/>`).join('')}${[0,1,2,3,4,5].map(i=>`<line x1="${px+i*(w-px*2)/5}" y1="14" x2="${px+i*(w-px*2)/5}" y2="${h-py}" class="ma-gridline vertical"/>`).join('')}<path d="${area}" fill="url(#${gid})"/><polyline points="${poly}" fill="none" stroke="${color}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${pts.filter((_,i)=>i%3===0||i===pts.length-1).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="${color}" stroke="#d8f6ff" stroke-width="1.5"/>`).join('')}</svg>`;
}
