function maMultiChart(series){
 const w=900,h=260,px=45,py=18,all=series.flatMap(x=>x.values),min=-20,max=60,colors=['#2695ff','#12d6c7','#d63be9'];
 return `<svg class="ma-multi-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${[-20,0,20,40,60].map(v=>{let y=h-py-(v-min)/(max-min)*(h-py*2);return `<line x1="${px}" y1="${y}" x2="${w-px}" y2="${y}" class="ma-gridline"/><text x="4" y="${y+4}" fill="#8da8c8" font-size="13">${v}%</text>`}).join('')}${Array.from({length:6},(_,i)=>`<line x1="${px+i*(w-px*2)/5}" y1="12" x2="${px+i*(w-px*2)/5}" y2="${h-py}" class="ma-gridline vertical"/>`).join('')}${series.map((ser,si)=>{let pts=ser.values.map((v,i)=>`${px+i*(w-px*2)/(ser.values.length-1)},${h-py-(v-min)/(max-min)*(h-py*2)}`).join(' ');return `<polyline points="${pts}" fill="none" stroke="${colors[si]}" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>`}).join('')}</svg>`;
}
